// Safely extract emails
const caseEmail = actions?.sfdc_int__case_email_ai?.records?.[0]?.SuppliedEmail;
// Contact Details not needed in first 5 use cases shared
const contactEmail = actions?.get_contact_details?.records?.[0]?.Email;

// Normalize emails
const normalizedCaseEmail = caseEmail ? caseEmail.trim().toLowerCase() : null;
const normalizedContactEmail = contactEmail ? contactEmail.trim().toLowerCase() : null;

// Initialize defaults
let isMatch = false;
let isAuthorisationRequired = true;

// Compare emails if both exist
if (normalizedCaseEmail && normalizedContactEmail) {
    isMatch = normalizedCaseEmail === normalizedContactEmail;
    isAuthorisationRequired = !isMatch; // true if no match, false if match
}

// Store results in form data
ZT.setFormData("email_match", isMatch);
ZT.setFormData("authorisation_required", isAuthorisationRequired);

// Debug logging
ZT.log(`Case Email: ${normalizedCaseEmail}`);
ZT.log(`Contact Email: ${normalizedContactEmail}`);
ZT.log(`Email Match Result: ${isMatch}`);
ZT.log(`Authorisation Required: ${isAuthorisationRequired}`);

