ZT.setFormData(
  "HtmlBody",
  (actions &&
    actions.automate_email_generation_int &&
    actions.automate_email_generation_int.email)
    ? actions.automate_email_generation_int.email
    : ""
);

function buildCaseReviewHtml() {
    /*
     * Dashboard HTML for the Case Review screen.
     *
     * Layout:
     *  - Full-width navy summary header
     *  - Left column:
     *      Case Details
     *      Subtopics found
     *  - Right column:
     *      Original Customer Email
     *      Email Response + AI feedback
     */

    function escapeHtml(value) {
        return String(
            value === null || value === undefined ? "" : value
        )
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
    }

    function formatValue(value) {
        if (
            value === null ||
            value === undefined ||
            value === ""
        ) {
            return '<span class="case-review-muted">—</span>';
        }

        if (typeof value === "boolean") {
            return escapeHtml(value ? "Yes" : "No");
        }

        if (Array.isArray(value)) {
            return value.length
                ? escapeHtml(value.join(", "))
                : '<span class="case-review-muted">—</span>';
        }

        if (typeof value === "object") {
            return escapeHtml(JSON.stringify(value));
        }

        return escapeHtml(String(value));
    }

    function renderRow(label, value) {
        return `
      <div class="case-review-row">
        <div class="case-review-row-label">
          ${escapeHtml(label)}
        </div>

        <div class="case-review-row-value">
          ${formatValue(value)}
        </div>
      </div>
    `;
    }

    /*
     * Available Subtopics.
     *
     * These match the values used in the Request Details form.
     */
    var subtopicOptions = [
    "Order New Card(s)",
    "Cancel card",
    "New User Request",
    "Active Card List",
    "Copy Invoice",
    "Replacement cards",
    "Card PIN(s)",
    "Transaction Report",
    "Lost & Stolen",
    "Account Unlock",
    "Forgotten Password"
  ];

    /*
     * Convert an automation intent value such as:
     *
     * order_a_new_card
     *
     * into the matching friendly subtopic:
     *
     * Order A New Card
     */
  function getSubtopicDisplayName(value) {
    /*
     * No intent returned.
     */
    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {
        return "";
    }

    /*
     * Always work with an array so we can support
     * both a single intent and multiple intents.
     *
     * Examples:
     *
     * "order_a_new_card"
     *
     * OR
     *
     * [
     *   "order_a_new_card",
     *   "replacement_card"
     * ]
     */
    var values = Array.isArray(value)
        ? value
        : [value];

    /*
     * Convert every detected intent into its
     * friendly ALL_INTENTS label.
     */
    var displayNames = values
        .map(function (item) {

            /*
             * Support object-based intent responses.
             */
            if (item && typeof item === "object") {
                item =
                    item.intent ||
                    item.name ||
                    item.key ||
                    item.value ||
                    item.intent_name ||
                    "";
            }

            if (!item) {
                return "";
            }

            var normalizedValue =
                normalizeIntentKey(item);

            /*
             * Find the friendly label using
             * ALL_INTENTS.
             */
            var match = ALL_INTENTS.find(
                function (intent) {
                    return (
                        normalizeIntentKey(intent.key) ===
                        normalizedValue
                    );
                }
            );

            /*
             * Use the mapped friendly label.
             *
             * If an unknown intent is returned,
             * fall back to its raw value.
             */
            return match
                ? match.label
                : String(item);

        })
        .filter(function (item) {
            return item !== "";
        });

    /*
     * Join all detected intents for the dashboard header.
     */
    return displayNames.join(", ");
}

    /*
     * Policy card retained for possible future use.
     * The card itself is commented out in the generated UI below.
     */
    function renderIntentCountFlag(label, count) {
        var safeCount =
            typeof count === "number" && !isNaN(count)
                ? count
                : 0;

        var isSingleIntent = safeCount === 1;
        var isMultipleIntents = safeCount >= 2;

        var theme = isMultipleIntents
            ? {
                cardBg: "#fce8e8",
                border: "#f0c9c9",
                pillBg: "#b91c1c",
                valueColor: "#b91c1c"
            }
            : isSingleIntent
                ? {
                    cardBg: "#e9faef",
                    border: "#d2eedc",
                    pillBg: "#16723a",
                    valueColor: "#16723a"
                }
                : {
                    cardBg: "#f3f6f9",
                    border: "#e2e8f0",
                    pillBg: "#64748b",
                    valueColor: "#475569"
                };

        return `
      <div
        class="case-review-flag-card"
        style="
          background:${theme.cardBg};
          border-color:${theme.border};
        "
      >
        <div class="case-review-flag-top">

          <div class="case-review-flag-title">
            ${escapeHtml(label)}
          </div>

          <div
            class="case-review-flag-pill"
            style="background:${theme.pillBg};"
          >
            ${escapeHtml(String(safeCount))}
          </div>

        </div>

        <div
          class="case-review-flag-value"
          style="color:${theme.valueColor};"
        >
          ${escapeHtml(String(safeCount))}
        </div>
      </div>
    `;
    }

    /*
     * All supported automated subtopics.
     */
    var ALL_INTENTS = [
        {
            key: "order_a_new_card",
        label: "Order New Card(s)"
        },
        {
            key: "cancel_card",
            label: "Cancel card"
        },
        {
            key: "new_user_request",
            label: "New User Request"
        },
        {
            key: "visa_card_activation",
            label: "Visa Card Activation"
        },
        {
            key: "active_card_list",
            label: "Active Card List"
        },
        {
            key: "copy_invoice",
            label: "Copy Invoice"
        },
        {
            key: "replacement_card",
            label: "Replacement cards"
        },
        {
            key: "card_pins",
            label: "Card PIN(s)"
        },
        {
            key: "transaction_report",
            label: "Transaction Report"
        },
        {
            key: "forgotten_password",
          label: "Forgotten Password"
        },
        {
          key: "lost_or_stolen_card",
          label: "Lost & Stolen"
        },
        {
          key: "account_unlock",
          label: "Account Unlock"
        }
    ];

    function normalizeIntentKey(value) {
        return String(value || "")
            .trim()
            .toLowerCase()
            .replace(/\s+/g, "_");
    }

    function normalizeIntents(rawIntents) {
        var intentsArray = Array.isArray(rawIntents)
            ? rawIntents
            : rawIntents
                ? [rawIntents]
                : [];

        return intentsArray
            .map(function (item) {
                if (typeof item === "string") {
                    return normalizeIntentKey(item);
                }

                if (item && typeof item === "object") {
                    return normalizeIntentKey(
                        item.intent ||
                        item.name ||
                        item.key ||
                        item.value ||
                        item.intent_name ||
                        ""
                    );
                }

                return "";
            })
            .filter(function (value) {
                return value !== "";
            });
    }

    function renderIntentPills(rawIntents) {
        var detected = normalizeIntents(rawIntents);

        return `
      <div class="case-review-intent-grid">

        ${ALL_INTENTS.map(function (intent) {
            var isPresent =
                detected.indexOf(intent.key) !== -1;

            var theme = isPresent
                ? {
                    cardBg: "#e8f5ec",
                    border: "#d3eadb",
                    valueColor: "#16803d",
                    text: "Yes"
                }
                : {
                    cardBg: "#fae9e9",
                    border: "#f2d2d2",
                    valueColor: "#c62525",
                    text: "No"
                };

            return `
            <div
              class="case-review-intent-simple-card"
              style="
                background:${theme.cardBg};
                border-color:${theme.border};
              "
            >
              <div class="case-review-intent-simple-title">
                ${escapeHtml(intent.label)}
              </div>

              <div
                class="case-review-intent-simple-value"
                style="color:${theme.valueColor};"
              >
                ${theme.text}
              </div>
            </div>
          `;
        }).join("")}

      </div>
    `;
    }

    /*
     * ========================================================
     * DATA
     * ========================================================
     */

    var emailResponse =
        actions &&
            actions.automate_email_generation_int &&
            actions.automate_email_generation_int.email
            ? actions.automate_email_generation_int.email
            : "";

    var existingAiFeedback =
        this && this.ai_feedback
            ? this.ai_feedback
            : "";

    var existingAiFeedbackComments =
        this && this.ai_feedback_comments
            ? this.ai_feedback_comments
            : "";

    var originalCustomerEmail =
        actions?.sfdc_int__case_email_ai
            ?.records?.[0]?.Description;

    /*
     * Raw automation value:
     *
     * Example:
     * order_a_new_card
     */
    var customerInquiry =
        actions?.automate_email_intent_int
            ?.email_intent;

    /*
     * Friendly display value based on subtopicOptions:
     *
     * Example:
     * Order A New Card
     */
    var customerRequest =
        getSubtopicDisplayName(customerInquiry);

    var confidenceScore =
        actions?.automate_email_intent_int
            ?.confidence_score;

    var confidenceExplanation =
        actions?.automate_email_intent_int
            ?.confidence_score_extracts;

    var caseNumber =
        typeof sf_CaseNumber !== "undefined"
            ? sf_CaseNumber
            : null;

    var requesterEmail =
        actions?.sfdc_int__case_email_ai
            ?.records?.[0]?.SuppliedEmail;

    var rawIntents =
        actions?.automate_email_intent_int
            ?.email_intent;

    var normalizedIntents =
        normalizeIntents(rawIntents);

    var detectedIntentCount =
      normalizedIntents.length;

    /*
    * Multi-intent indicators.
    */
    var hasMultipleIntents =
      detectedIntentCount > 1
        ? "true"
        : "false";

    ZT.setFormData(
      "has_multiple_intents",
      hasMultipleIntents
    );

    var confidenceScore =
        actions?.automate_email_intent_int
            ?.confidence_score;

    ZT.setFormData(
        "confidence_score",
        confidenceScore ?? ""
    );

    /*
     * ========================================================
     * DASHBOARD HTML
     * ========================================================
     */

    var html = `
    <div class="case-review-shell">

      <div class="case-review-panel">

        <!-- =======================================
             HEADER / HERO
             ======================================= -->
        <div class="case-review-hero">

          <div class="case-review-hero-top">

            <div class="case-review-hero-copy">

              <div class="case-review-eyebrow">
                Case Review
              </div>

              <h2 class="case-review-main-title">
                Email Response Summary
              </h2>

              <div class="case-review-subtitle">
                Case
                <strong>
                  ${formatValue(caseNumber)}
                </strong>

                <span class="case-review-subtitle-separator">
                  ·
                </span>

                ${formatValue(customerRequest)}
              </div>

            </div>

            <div class="case-review-hero-metrics-card">

              <div class="case-review-hero-metric">

                <div class="case-review-hero-metric-label">
                  Confidence Score
                </div>

                <div class="case-review-hero-metric-value">
                  ${formatValue(confidenceScore)}
                </div>

              </div>

              <div class="case-review-hero-metric">

                <div class="case-review-hero-metric-label">
                  Confidence Explanation
                </div>

                <div class="case-review-hero-metric-text">
                  ${formatValue(confidenceExplanation)}
                </div>

              </div>

            </div>

          </div>

        </div>


        <!-- =======================================
             DASHBOARD BODY
             ======================================= -->
        <div class="case-review-body">

          <div class="case-review-grid">


            <!-- ===================================
                 LEFT COLUMN
                 =================================== -->
            <div
              class="
                case-review-col
                case-review-col-left
              "
            >

              <!-- Case Details -->
              <div class="case-review-card">

                <h3 class="case-review-card-title">
                  Case Details
                </h3>

                ${renderRow(
        "Case Number",
        caseNumber
    )}

                ${renderRow(
        "Customer Request",
        customerRequest
    )}

                ${renderRow(
        "Requester Email",
        requesterEmail
    )}

              </div>


              <!--
              =================================================
              POLICY FLAGS

              Temporarily disabled.

              Keeping this code here so it can easily be
              restored later.

              <div class="case-review-card">

                <h3 class="case-review-card-title">
                  Policy Flags
                </h3>

                ${renderIntentCountFlag(
        "Detected Intents",
        detectedIntentCount
    )}

              </div>
              =================================================
              -->


              <!-- Subtopics -->
              <div class="case-review-card">

                <h3 class="case-review-card-title">
                  Subtopics found
                </h3>

                ${renderIntentPills(rawIntents)}

              </div>

            </div>


            <!-- ===================================
                 RIGHT COLUMN
                 =================================== -->
            <div
              class="
                case-review-col
                case-review-col-right
              "
            >

              <!-- Original Email -->
              <div class="case-review-card">

                <h3 class="case-review-card-title">
                  Original Customer Email
                </h3>

                <div class="case-review-html-card-body">
                  ${originalCustomerEmail &&
            String(
                originalCustomerEmail
            ).trim() !== ""
            ? String(
                originalCustomerEmail
            )
            : '<span class="case-review-muted">—</span>'
        }
                </div>

              </div>


              <!-- Generated Response -->
              <div
                class="
                  case-review-card
                  case-review-response-card
                "
              >

                <h3 class="case-review-card-title">
                  Email Response
                </h3>

                <div class="case-review-html-card-body">
                  ${emailResponse &&
            String(emailResponse)
                .trim() !== ""
            ? String(emailResponse)
            : '<span class="case-review-muted">—</span>'
        }
                </div>

                ${renderAiFeedback(
            existingAiFeedback,
            existingAiFeedbackComments
        )
        }

              </div>

            </div>

          </div>

        </div>

      </div>

    </div>
  `;

    return html.trim();
}

function buildRequestFormHtml() {
  /**
   * Escapes values before inserting them into generated HTML.
   */
  function escapeHtml(value) {
    return String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  /**
   * Creates the <option> elements for a dropdown.
   */
  function buildOptions(options, selectedValue, placeholder) {
    var html = `<option value="">${escapeHtml(placeholder)}</option>`;

    options.forEach(function (option) {
      var selected =
        option === selectedValue
          ? ' selected="selected"'
          : "";

      html += `
        <option value="${escapeHtml(option)}"${selected}>
          ${escapeHtml(option)}
        </option>
      `;
    });

    return html;
  }

  /*
   * Topic dropdown options.
   * Previously named typeOptions.
   */
  var topicOptions = [
    "Online",
    "Other"
  ];

  /*
   * Subtopic dropdown options.
   * Previously named subtypeOptions.
   */
  var subtopicOptions = [
    "Order New Card(s)",
    "Cancel card",
    "New User Request",
    "Active Card List",
    "Copy Invoice",
    "Replacement cards",
    "Card PIN(s)",
    "Transaction Report",
    "Lost & Stolen",
    "Account Unlock",
    "Forgotten Password"
  ];

  /*
   * Restore previously selected form-data values when the node renders again.
   */
  var selectedTopic = this?.sf_Topic__c || "";
  var selectedSubtopic = this?.sf_Sub_Topic__c || "";

  var htmlBody = ZT.getVariableValue("HtmlBody", null);

  /*
 * Original customer email from the Salesforce action.
 */
var originalCustomerEmail =
        actions?.sfdc_int__case_email_ai
            ?.records?.[0]?.Description;

  return `
    <div class="zt-form-card">
    <!-- Customer's original email -->
      <div class="zt-form-header">
        <h2 class="zt-form-title">Original Customer Email</h2>
        <p class="zt-form-subtitle">${escapeHtml(originalCustomerEmail)}</p>
      </div>
      <div class="zt-form-header">
        <h2 class="zt-form-title">Request Details</h2>
        <p class="zt-form-subtitle">Complete the fields below.</p>
      </div>

      <div class="zt-form-grid">

        <!-- Topic -->
        <div class="zt-form-field">
          <label
            for="sf_Topic__c"
            class="zt-form-label"
          >
            Topic <span class="zt-required">*</span>
          </label>

          <select
            id="sf_Topic__c"
            name="sf_Topic__c"
            data-name="sf_Topic__c"
            class="zt-data zt-form-control"
            required
          >
            ${buildOptions(
    topicOptions,
    selectedTopic,
    "Select Topic"
  )}
          </select>
        </div>

        <!-- Subtopic -->
        <div class="zt-form-field">
          <label
            for="sf_Sub_Topic__c"
            class="zt-form-label"
          >
            Subtopic <span class="zt-required">*</span>
          </label>

          <select
            id="sf_Sub_Topic__c"
            name="sf_Sub_Topic__c"
            data-name="sf_Sub_Topic__c"
            class="zt-data zt-form-control"
            required
          >
            ${buildOptions(
    subtopicOptions,
    selectedSubtopic,
    "Select Subtopic"
  )}
          </select>
        </div>

      </div>

      <div class="zt-form-field zt-form-field-full">
        <label class="zt-form-label">HTML Body</label>

        <div
          id="htmlBodyEditor"
          class="zt-rich-editor"
          contenteditable="true"
        >${htmlBody || "<p>Start typing...</p>"}</div>

        <textarea
          id="HtmlBody"
          name="HtmlBody"
          data-name="HtmlBody"
          class="zt-data"
          style="display:none;"
        >${escapeHtml(htmlBody)}</textarea>

        <div class="zt-form-help">
          Format text visually (bold, line breaks, etc.)
        </div>
      </div>
    </div>
  `.trim();
}

ZT.setTransformData("case_review_html", buildCaseReviewHtml());
ZT.setTransformData("requestFormHtml", buildRequestFormHtml());

ZT.log("Transforms created: case_review_html, requestFormHtml");

/**
 * Builds the thumbs up/down widget shown inside the Email Response card.
 *
 * The selected value is stored in:
 * - ai_feedback = "thumbs_up"
 * - ai_feedback = "thumbs_down"
 */
/**
 * Builds the thumbs up/down feedback widget.
 *
 * Form-data variables:
 * - ai_feedback = "thumbs_up" or "thumbs_down"
 * - ai_feedback_comments = user-entered comments
 */
function renderAiFeedback(existingFeedback, existingComments) {
  var feedbackValue = String(existingFeedback || "");
  var commentsValue = String(existingComments || "");

  /**
   * Escapes text placed inside an HTML attribute or textarea.
   */
  function escapeFeedbackHtml(value) {
    return String(value || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  /*
   * Once feedback and comments have already been submitted,
   * show the completed state when the node renders again.
   */
  if (feedbackValue === "thumbs_up") {
    return `
      <div class="ai-feedback-wrap">
        <div class="ai-feedback-thankyou">
          👍 Thanks for your feedback!
        </div>
      </div>
    `;
  }

  if (
    feedbackValue === "thumbs_down" &&
    commentsValue.trim() !== ""
  ) {
    return `
      <div class="ai-feedback-wrap">
        <div class="ai-feedback-thankyou">
          👎 Thanks for your feedback — we’ll use it to improve.
        </div>
      </div>
    `;
  }

  /*
   * If thumbs-down was previously selected but no comments were
   * submitted, restore the comments section in its visible state.
   */
  var showComments = feedbackValue === "thumbs_down";

  return `
    <div class="ai-feedback-wrap">
      <div class="ai-feedback-label">Was this helpful?</div>

      <input
        type="hidden"
        class="zt-data ai-feedback-value"
        id="ai_feedback"
        name="ai_feedback"
        data-name="ai_feedback"
        value="${escapeFeedbackHtml(feedbackValue)}"
      />

      <div class="ai-feedback-buttons">
        <button
          type="button"
          class="ai-feedback-btn ${feedbackValue === "thumbs_up" ? "selected" : ""
    }"
          data-feedback="thumbs_up"
          aria-label="Helpful"
          title="Helpful"
        >
          👍
        </button>

        <button
          type="button"
          class="ai-feedback-btn ${feedbackValue === "thumbs_down" ? "selected" : ""
    }"
          data-feedback="thumbs_down"
          aria-label="Not helpful"
          title="Not helpful"
        >
          👎
        </button>
      </div>

      <div
        class="ai-feedback-comments ${showComments ? "is-visible" : ""
    }"
        aria-hidden="${showComments ? "false" : "true"}"
      >
        <label
          for="ai_feedback_comments"
          class="ai-feedback-comments-label"
        >
          What could be improved?
        </label>

        <textarea
          id="ai_feedback_comments"
          name="ai_feedback_comments"
          data-name="ai_feedback_comments"
          class="zt-data ai-feedback-comments-input"
          rows="4"
          placeholder="Tell us what was incorrect or could be improved..."
        >${escapeFeedbackHtml(commentsValue)}</textarea>

        <div
          class="ai-feedback-comments-error"
          role="alert"
          aria-live="polite"
        ></div>

        <button
          type="button"
          class="ai-feedback-submit"
        >
          Submit feedback
        </button>
      </div>
    </div>
  `;
}

/**
 * Builds the form shown when the AI detects
 * more than one subtopic.
 *
 * The user's selection is stored in:
 *
 * sf_Sub_Topic__c
 */
function buildMultipleSubtopicsFormHtml() {

    /**
     * Escape values before inserting them into HTML.
     */
    function escapeHtml(value) {
        return String(
            value === null || value === undefined
                ? ""
                : value
        )
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#39;");
    }


    /**
     * Normalize an intent key.
     */
    function normalizeIntentKey(value) {
        return String(value || "")
            .trim()
            .toLowerCase()
            .replace(/\s+/g, "_");
    }


    /**
     * Same intent mapping used by the dashboard.
     *
     * Raw AI intent key
     * ->
     * Friendly Salesforce / UI label
     */
    var ALL_INTENTS = [
        {
            key: "order_a_new_card",
            label: "Order New Card(s)"
        },
        {
            key: "cancel_card",
            label: "Cancel card"
        },
        {
            key: "new_user_request",
            label: "New User Request"
        },
        {
            key: "visa_card_activation",
            label: "VISA Card activation"
        },
        {
            key: "active_card_list",
            label: "Active Card List"
        },
        {
