        },
        {
            key: "forgotten_password",
            label: "Forgotten Password"
        },
        {
            key: "lost_or_stolen_card",
            label: "Lost & Stolen"
        },
        {
            key: "account_unlock",
            label: "Account Unlock"
        }
    ];


    /**
     * Get all intents returned by the automation.
     *
     * Example:
     *
     * [
     *   "order_a_new_card",
     *   "replacement_card"
     * ]
     */
    var rawIntents =
        actions?.automate_email_intent_int
            ?.email_intent;


    /**
     * Always convert the result to an array.
     *
     * This supports both:
     *
     * "order_a_new_card"
     *
     * and:
     *
     * [
     *   "order_a_new_card",
     *   "replacement_card"
     * ]
     */
    var detectedIntents =
        Array.isArray(rawIntents)
            ? rawIntents
            : rawIntents
                ? [rawIntents]
                : [];


    /**
     * Convert the raw AI intent keys into
     * friendly dropdown labels.
     */
    var detectedSubtopics =
        detectedIntents
            .map(function (item) {

                /**
                 * Support object-based intent responses too.
                 *
                 * Examples:
                 *
                 * { intent: "order_a_new_card" }
                 * { key: "order_a_new_card" }
                 */
                if (
                    item &&
                    typeof item === "object"
                ) {
                    item =
                        item.intent ||
                        item.name ||
                        item.key ||
                        item.value ||
                        item.intent_name ||
                        "";
                }

                var normalized =
                    normalizeIntentKey(item);

                /**
                 * Match the raw AI key against ALL_INTENTS.
                 */
                var match =
                    ALL_INTENTS.find(
                        function (intent) {
                            return (
                                normalizeIntentKey(
                                    intent.key
                                ) === normalized
                            );
                        }
                    );

                /**
                 * Return the friendly label.
                 *
                 * If the AI returns an unknown intent,
                 * fall back to the raw value.
                 */
                return match
                    ? match.label
                    : String(item || "");
            })
            .filter(function (value) {
                return value !== "";
            });


    /**
     * Remove duplicates, just in case the automation
     * returns the same intent more than once.
     */
    detectedSubtopics =
        detectedSubtopics.filter(
            function (value, index, array) {
                return array.indexOf(value) === index;
            }
        );


    /**
     * Restore the current sf_Sub_Topic__c value
     * if this node renders again.
     */
    var selectedSubtopic =
        this?.sf_Sub_Topic__c || "";


    /**
     * Build the dropdown.
     */
    var optionsHtml = `
        <option value="">
            Select Subtopic
        </option>
    `;


    detectedSubtopics.forEach(
        function (subtopic) {

            var selected =
                subtopic === selectedSubtopic
                    ? ' selected="selected"'
                    : "";

            optionsHtml += `
                <option
                    value="${escapeHtml(subtopic)}"
                    ${selected}
                >
                    ${escapeHtml(subtopic)}
                </option>
            `;
        }
    );


    /**
     * Build and return the form HTML.
     */
    return `
        <div class="zt-form-card">

            <div class="zt-form-header">

                <h2 class="zt-form-title">
                    Multiple Subtopics Detected
                </h2>

                <p class="zt-form-subtitle">
                    Multiple Subtopics were detected,
                    please choose from the following:
                </p>

            </div>


            <div class="zt-form-field">

                <label
                    for="sf_Sub_Topic__c"
                    class="zt-form-label"
                >
                    Subtopic
                    <span class="zt-required">*</span>
                </label>

                <select
                    id="sf_Sub_Topic__c"
                    name="sf_Sub_Topic__c"
                    data-name="sf_Sub_Topic__c"
                    class="zt-data zt-form-control"
                    required
                >
                    ${optionsHtml}
                </select>

            </div>

        </div>
    `.trim();
}


/**
 * Store the generated HTML in the transforms namespace.
 *
 * Surface this on a Content Node using:
 *
 * ${transforms.multipleSubtopicsFormHtml}
 */
ZT.setTransformData(
    "multipleSubtopicsFormHtml",
    buildMultipleSubtopicsFormHtml()
);

ZT.log(
    "Transform created: multipleSubtopicsFormHtml"
);

