// ============================================================
// Send Email - success/failure + error extraction
//
// Sets:
//   emailSent = "true" / "false"
//   errorEmailMessage = "" on success, otherwise best error found
//
// Handles:
//
// 1. Normal success/failure emailSimple response
// 2. Connected Object / HTTP failure response
// 3. Missing action
// 4. Unexpected exceptions
// ============================================================

var EMAIL_ACTION_ALIAS = "send_email_simple_int";

try {
  var emailAction = actions && actions[EMAIL_ACTION_ALIAS];

  // ----------------------------------------------------------
  // Recursively find the emailSimple result object.
  //
  // Example:
  //
  // {
  //   actionName: "emailSimple",
  //   isSuccess: true/false,
  //   errors: [...]
  // }
  // ----------------------------------------------------------
  function findEmailResult(obj, depth) {
    if (obj === null || typeof obj !== "object" || depth > 8) {
      return null;
    }

    if (
      obj.actionName === "emailSimple" &&
      typeof obj.isSuccess === "boolean"
    ) {
      return obj;
    }

    var keys = Object.keys(obj);

    for (var i = 0; i < keys.length; i++) {
      var found = findEmailResult(obj[keys[i]], depth + 1);

      if (found) {
        return found;
      }
    }

    return null;
  }

  // ----------------------------------------------------------
  // Recursively find Zingtree HTTP response metadata.
  //
  // Example failure:
  //
  // {
  //   _zt_meta: {
  //     response: {
  //       code: 400,
  //       body: [
  //         {
  //           errorCode: "JSON_PARSER_ERROR",
  //           message: "Unexpected character..."
  //         }
  //       ]
  //     }
  //   }
  // }
  // ----------------------------------------------------------
  function findResponse(obj, depth) {
    if (obj === null || typeof obj !== "object" || depth > 8) {
      return null;
    }

    if (
      obj._zt_meta &&
      obj._zt_meta.response
    ) {
      return obj._zt_meta.response;
    }

    var keys = Object.keys(obj);

    for (var i = 0; i < keys.length; i++) {
      var found = findResponse(obj[keys[i]], depth + 1);

      if (found) {
        return found;
      }
    }

    return null;
  }

  var emailResult = emailAction
    ? findEmailResult(emailAction, 0)
    : null;

  var response = emailAction
    ? findResponse(emailAction, 0)
    : null;

  var emailSent = false;
  var errorEmailMessage = "";

  // ----------------------------------------------------------
  // CASE 1:
  // We received an actual emailSimple result.
  // ----------------------------------------------------------
  if (emailResult) {

    emailSent = emailResult.isSuccess === true;

    // Only populate an error when the email failed.
    if (!emailSent) {

      if (
        Array.isArray(emailResult.errors) &&
        emailResult.errors.length > 0
      ) {
        var emailError = emailResult.errors[0];

        if (emailError && emailError.message) {
          errorEmailMessage = emailError.message;
        } else {
          errorEmailMessage = "Email failed with no error message.";
        }

      } else {
        errorEmailMessage = "Email failed with no error message.";
      }
    }

  // ----------------------------------------------------------
  // CASE 2:
  // No emailSimple result was returned because the Connected
  // Object itself failed.
  //
  // Look for an error in:
  // _zt_meta.response.body[0].message
  // ----------------------------------------------------------
  } else if (
    response &&
    Array.isArray(response.body) &&
    response.body.length > 0
  ) {

    var responseError = response.body[0];

    if (responseError && responseError.message) {
      errorEmailMessage = responseError.message;
    } else {
      errorEmailMessage =
        "Email request failed with no error message.";
    }

  // ----------------------------------------------------------
  // CASE 3:
  // The connected-object action wasn't available.
  // ----------------------------------------------------------
  } else if (!emailAction) {

    errorEmailMessage =
      "Email action not found: " + EMAIL_ACTION_ALIAS;

  // ----------------------------------------------------------
  // CASE 4:
  // We got an action response, but it didn't match any known
  // response shape.
  // ----------------------------------------------------------
  } else {

    errorEmailMessage =
      "Email failed with no error message.";
  }

  // ----------------------------------------------------------
  // Store as STRINGS rather than booleans.
  //
  // This ensures false remains visible/present in form data:
  //
  // emailSent = "true"
  // emailSent = "false"
  // ----------------------------------------------------------
  ZT.setFormData(
    "emailSent",
    emailSent ? "true" : "false"
  );

  ZT.setFormData(
    "errorEmailMessage",
    errorEmailMessage
  );

  // ----------------------------------------------------------
  // Logging
  // ----------------------------------------------------------
  ZT.log(
    "EMAIL CHECK: " +
    EMAIL_ACTION_ALIAS +
    " -> emailSent=" +
    (emailSent ? "true" : "false") +
    (response
      ? " | HTTP " + response.code
      : "") +
    (errorEmailMessage
      ? " | error=" + errorEmailMessage
      : "")
  );

} catch (err) {

  // ----------------------------------------------------------
  // Unexpected script error.
  // Always fail safely.
  // ----------------------------------------------------------
  var exceptionMessage =
    "Email check exception: " +
    (
      err && err.message
        ? err.message
        : String(err)
    );

  ZT.setFormData(
    "emailSent",
    "false"
  );

  ZT.setFormData(
    "errorEmailMessage",
    exceptionMessage
  );

  ZT.log(
    "EMAIL CHECK: exception -> " +
    exceptionMessage
  );
}

// build final message
function buildEmailSentSummaryHtml() {
  function escapeHtml(value) {
    return String(value === null || value === undefined ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function formatValue(value) {
    if (value === null || value === undefined || value === "") {
      return '<span class="email-summary-muted">—</span>';
    }

    return escapeHtml(String(value));
  }

  function renderRow(label, value) {
    return `
      <div class="email-summary-row">
        <div class="email-summary-row-label">${escapeHtml(label)}</div>
        <div class="email-summary-row-value">${formatValue(value)}</div>
      </div>
    `;
  }

  function renderHtmlCard(label, htmlValue) {
    var hasValue = htmlValue && String(htmlValue).trim() !== "";

    return `
      <div class="email-summary-card">
        <h3 class="email-summary-card-title">${escapeHtml(label)}</h3>
        <div class="email-summary-html-body">
          ${hasValue ? String(htmlValue) : '<span class="email-summary-muted">—</span>'}
        </div>
      </div>
    `;
  }

  var topicValue = typeof sf_Topic__c !== "undefined" ? sf_Topic__c : "";
  var subTopicValue = typeof sf_Sub_Topic__c !== "undefined" ? sf_Sub_Topic__c : "";
  var htmlBodyValue = typeof HtmlBody !== "undefined" ? HtmlBody : "";

  return `
    <div class="email-summary-card-shell">
      <div class="email-summary-header">
        <div class="email-summary-icon">✓</div>
        <div class="email-summary-header-copy">
          <h2 class="email-summary-title">Email Sent Successfully</h2>
          <p class="email-summary-subtitle">
            Great, the email was sent and the Salesforce fields below were updated.
          </p>
        </div>
      </div>

      <div class="email-summary-card">
  <h3 class="email-summary-card-title">Updated Salesforce Fields</h3>
  ${renderRow("Topic", topicValue)}
  ${renderRow("Sub Topic", subTopicValue)}
</div>

      ${renderHtmlCard("Email Sent", htmlBodyValue)}
    </div>
  `.trim();
}

ZT.setTransformData("email_sent_summary_html", buildEmailSentSummaryHtml());
ZT.log("Transform created: email_sent_summary_html");

