/**
 * Determines AI account eligibility based on:
 *
 * 1. Framework__c must be null
 * 2. Account_Segment__c must be null, "SME", or "Keyfuels"
 * 3. AS_Account_Administrator__c must be in the approved list
 *
 * ALL THREE conditions must be satisfied.
 *
 * @returns {boolean}
 */
function getAIAccountEligibility() {
    const account =
        actions?.get_account_details__int?.records?.[0];

    // If no account record exists, it cannot be eligible.
    if (!account) {
        return false;
    }

    // 1. Framework must be null.
    const frameworkEligible =
        account.Framework__c == null;

    // 2. Account Segment must be null, SME, or Keyfuels.
    const segmentEligible =
        account.Account_Segment__c == null ||
        account.Account_Segment__c === "SME" ||
        account.Account_Segment__c === "Keyfuels";

    // 3. Account Administrator must be in this list.
    const eligibleAdministrators = [
        "SME Unmanaged",
        "AS New CMT",
        "TFC CMT",
        "TFC NEW CMT",
        "Fuelcards4u",
        "TFC 1",
        "TFC 2",
        "TFC 3",
        "TFC 4",
        "TFC 5",
        "TFC 6",
        "TL AS",
        "TL TFC",
        "AS HC1",
        "AS HC2",
        "AS HC3",
        "AS HC4",
        "AS HC5"
    ];

    const administratorEligible =
        eligibleAdministrators.includes(
            account.AS_Account_Administrator__c
        );

    // ALL three conditions must be true.
    return (
        frameworkEligible &&
        segmentEligible &&
        administratorEligible
    );
}


// Calculate eligibility.
const aiAccountEligibility = getAIAccountEligibility();

// Store actual boolean true/false in Form Data.
ZT.setFormData(
    "ai_account_eligibility",
    aiAccountEligibility
);

// Debugging.
ZT.log(
    `ai_account_eligibility: ${aiAccountEligibility}`
);

